def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    from fractions import Fraction

    jump = dict(jumps)

    def destination(cell: int) -> int:
        while cell in jump:
            cell = jump[cell]
        return cell

    transitions = {}
    reachable = {0}
    stack = [0]

    while stack:
        cell = stack.pop()
        counts = {}
        for roll in range(1, m + 1):
            landing = cell + roll
            if landing > n:
                landing = 2 * n - landing
            landing = destination(landing)
            counts[landing] = counts.get(landing, 0) + 1
            if landing != n and landing not in reachable:
                reachable.add(landing)
                stack.append(landing)
        transitions[cell] = counts

    reverse = {cell: [] for cell in reachable}
    reverse[n] = []
    for cell, counts in transitions.items():
        for landing in counts:
            reverse[landing].append(cell)

    can_finish = {n}
    stack = [n]
    while stack:
        cell = stack.pop()
        for previous in reverse[cell]:
            if previous not in can_finish:
                can_finish.add(previous)
                stack.append(previous)

    if not reachable.issubset(can_finish):
        return None

    states = sorted(reachable)
    index = {cell: i for i, cell in enumerate(states)}
    size = len(states)
    matrix = [[0] * (size + 1) for _ in range(size)]

    for cell in states:
        i = index[cell]
        matrix[i][i] = m
        matrix[i][size] = m
        for landing, count in transitions[cell].items():
            if landing != n:
                matrix[i][index[landing]] -= count

    previous_pivot = 1
    for k in range(size - 1):
        if matrix[k][k] == 0:
            for row in range(k + 1, size):
                if matrix[row][k] != 0:
                    matrix[k], matrix[row] = matrix[row], matrix[k]
                    break

        pivot = matrix[k][k]
        for i in range(k + 1, size):
            factor = matrix[i][k]
            for j in range(k + 1, size + 1):
                matrix[i][j] = (
                    matrix[i][j] * pivot - factor * matrix[k][j]
                ) // previous_pivot
            matrix[i][k] = 0
        previous_pivot = pivot

    solution = [Fraction(0) for _ in range(size)]
    for i in range(size - 1, -1, -1):
        value = Fraction(matrix[i][size])
        for j in range(i + 1, size):
            value -= matrix[i][j] * solution[j]
        solution[i] = value / matrix[i][i]

    result = solution[index[0]]
    return [result.numerator, result.denominator]
